import torch

def train_one_epoch(model, loader, optimizer, loss_fn, device):
    model.train(); total_loss = 0.0; total_items = 0
    for x, y in loader:
        x, y = x.to(device), y.to(device)
        optimizer.zero_grad(set_to_none=True)
        logits = model(x); loss = loss_fn(logits, y)
        loss.backward(); optimizer.step()
        n = y.size(0); total_loss += loss.detach().item() * n; total_items += n
    return total_loss / max(total_items, 1)

import torch

def evaluate(model, loader, loss_fn, device):
    model.eval(); total_loss = 0.0; total = 0; correct = 0
    with torch.inference_mode():
        for x, y in loader:
            x, y = x.to(device), y.to(device)
            logits = model(x); loss = loss_fn(logits, y)
            n = y.size(0); total_loss += loss.item() * n
            correct += (logits.argmax(dim=1) == y).sum().item(); total += n
    return {"loss": total_loss / max(total, 1), "accuracy": correct / max(total, 1)}
